insert into public.products (slug, name, description, price, currency, category, material, images, stock, created_at) values
  ('sol-signet-ring', 'Sol Signet Ring', 'A small, smooth signet ring with a softly domed face. It sits comfortably on the little finger or index finger and pairs well with stacking bands. Polished by hand and finished with a light satin edge.', 4200, 'KES', 'rings', '925 sterling silver', array['/images/products/sol-signet-ring-1.svg','/images/products/sol-signet-ring-2.svg','/images/products/sol-signet-ring-3.svg'], 8, now() - interval '0 hours'),
  ('twist-stacking-ring', 'Twist Stacking Ring', 'A slim twisted band made to be worn alone or stacked with others. The rope texture catches the light without feeling busy, and the thin profile stays comfortable through a full day of wear.', 3800, 'KES', 'rings', '18k gold-plated sterling silver', array['/images/products/twist-stacking-ring-1.svg','/images/products/twist-stacking-ring-2.svg','/images/products/twist-stacking-ring-3.svg'], 3, now() - interval '1 hours'),
  ('moonstone-band-ring', 'Moonstone Band Ring', 'A plain band set with a single milky moonstone. The stone flashes a pale blue glow in daylight. Currently sold out, check back soon for the next small batch.', 5600, 'KES', 'rings', '925 sterling silver, moonstone', array['/images/products/moonstone-band-ring-1.svg','/images/products/moonstone-band-ring-2.svg','/images/products/moonstone-band-ring-3.svg'], 0, now() - interval '2 hours'),
  ('petal-pendant-necklace', 'Petal Pendant Necklace', 'A fine chain with a single petal-shaped pendant that rests just below the collarbone. Light enough to forget you are wearing it, and simple enough to layer with longer chains.', 6900, 'KES', 'necklaces', '18k gold-plated sterling silver', array['/images/products/petal-pendant-necklace-1.svg','/images/products/petal-pendant-necklace-2.svg','/images/products/petal-pendant-necklace-3.svg'], 12, now() - interval '3 hours'),
  ('fine-chain-necklace', 'Fine Chain Necklace', 'A delicate cable chain with a small bar charm. An everyday basic that works under a shirt collar or over a knit. Adjustable clasp fits 40 to 45 cm.', 4800, 'KES', 'necklaces', '925 sterling silver', array['/images/products/fine-chain-necklace-1.svg','/images/products/fine-chain-necklace-2.svg','/images/products/fine-chain-necklace-3.svg'], 2, now() - interval '4 hours'),
  ('coin-drop-necklace', 'Coin Drop Necklace', 'A round, lightly hammered coin hangs from a sturdy link chain. The hammered surface gives each piece its own pattern, so no two are exactly alike.', 7400, 'KES', 'necklaces', 'Gold-plated brass', array['/images/products/coin-drop-necklace-1.svg','/images/products/coin-drop-necklace-2.svg','/images/products/coin-drop-necklace-3.svg'], 6, now() - interval '5 hours'),
  ('silver-hoop-earrings', 'Silver Hoop Earrings', 'Classic medium hoops with a hidden hinge clasp. Lightweight enough for all-day wear, with a smooth polished finish that works with both casual and dressed-up outfits.', 3500, 'KES', 'earrings', '925 sterling silver', array['/images/products/silver-hoop-earrings-1.svg','/images/products/silver-hoop-earrings-2.svg','/images/products/silver-hoop-earrings-3.svg'], 15, now() - interval '6 hours'),
  ('pearl-stud-earrings', 'Pearl Stud Earrings', 'Small freshwater pearl studs on sterling silver posts. A quiet pair that goes with almost everything and suits sensitive ears thanks to the silver backing.', 3200, 'KES', 'earrings', '925 sterling silver, freshwater pearl', array['/images/products/pearl-stud-earrings-1.svg','/images/products/pearl-stud-earrings-2.svg','/images/products/pearl-stud-earrings-3.svg'], 20, now() - interval '7 hours'),
  ('drop-leaf-earrings', 'Drop Leaf Earrings', 'A tiny leaf shape hangs from a short hook, moving gently as you walk. The gold plating is thick enough for regular wear when you take care of it.', 5200, 'KES', 'earrings', '18k gold-plated sterling silver', array['/images/products/drop-leaf-earrings-1.svg','/images/products/drop-leaf-earrings-2.svg','/images/products/drop-leaf-earrings-3.svg'], 1, now() - interval '8 hours'),
  ('beaded-chain-bracelet', 'Beaded Chain Bracelet', 'A slim bracelet of small silver beads on a flexible chain. Wear it on its own or with a watch. Fits wrists of 15 to 18 cm with an extender chain.', 4100, 'KES', 'bracelets', '925 sterling silver', array['/images/products/beaded-chain-bracelet-1.svg','/images/products/beaded-chain-bracelet-2.svg','/images/products/beaded-chain-bracelet-3.svg'], 9, now() - interval '9 hours'),
  ('hammered-cuff-bracelet', 'Hammered Cuff Bracelet', 'An open cuff with a hand-hammered surface that slips on easily and can be gently adjusted for a snug fit. A bold piece that still feels light.', 6200, 'KES', 'bracelets', 'Gold-plated brass', array['/images/products/hammered-cuff-bracelet-1.svg','/images/products/hammered-cuff-bracelet-2.svg','/images/products/hammered-cuff-bracelet-3.svg'], 4, now() - interval '10 hours'),
  ('rope-link-bracelet', 'Rope Link Bracelet', 'Soft rose-toned links twisted into a rope pattern with a secure lobster clasp. Warm against the skin and easy to pair with silver or gold.', 5900, 'KES', 'bracelets', 'Rose gold-plated sterling silver', array['/images/products/rope-link-bracelet-1.svg','/images/products/rope-link-bracelet-2.svg','/images/products/rope-link-bracelet-3.svg'], 7, now() - interval '11 hours');
